public static double calculateAverageBalance(List<Double> closingBalances) {
    if (closingBalances == null || closingBalances.isEmpty()) {
        return 0.0;
    }
    double sum = 0.0;
    for (Double balance : closingBalances) {
        if (balance == null) {
            continue;
        }
        sum += balance;
    }
    double average = sum / closingBalances.size();
    return Math.round(average * 100.0) / 100.0;
}

public static int findNthLeapYear(int Y, int N) {
    if (Y <= 0 || N <= 0) {
        throw new IllegalArgumentException("Y and N must be positive integers");
    }
    int count = 0;
    int year = Y + 1;
    while (true) {
        if (isLeapYear(year)) {
            count++;
            if (count == N) {
                return year;
            }
        }
        year++;
    }
}

