            // Actually paths structure: each path is an array of two coordinates? Let me reconsider.
            // From similar problems, paths is likely a list of edges, each edge is [node1, node2] where nodes are coordinates
            // But more likely, paths is an array where each element is an edge represented as two coordinate arrays
            // Let's assume paths[i] is an array of two elements, each a coordinate array
        }
    }

    // Different interpretation: paths[i] = {x1, y1, x2, y2} or paths is a list of pairs of coordinates
    // Let's use BFS/DFS approach. Convert coordinates to 1D index: id = x * n + y
    // Build adjacency list from paths
    Map<Integer, List<Integer>> adj = new HashMap<>();
    if (paths != null) {
        for (int[] path : paths) {
            if (path == null || path.length == 0) continue;
            try {
                if (path.length >= 4) {
                    int x1 = path[0], y1 = path[1], x2 = path[2], y2 = path[3];
                    int id1 = x1 * n + y1;
                    int id2 = x2 * n + y2;
                    if (id1 >= 0 && id1 < n * n && id2 >= 0 && id2 < n * n) {
                        adj.computeIfAbsent(id1, k -> new ArrayList<>()).add(id2);
                        adj.computeIfAbsent(id2, k -> new ArrayList<>()).add(id1);
                    }
                } else if (path.length >= 2 && path[0] instanceof Integer && path[1] instanceof Integer) {
                    // path is a pair of 1D indices
                    int id1 = (Integer) path[0];
                    int id2 = (Integer) path[1];
                    if (id1 >= 0 && id1 < n * n && id2 >= 0 && id2 < n * n) {
                        adj.computeIfAbsent(id1, k -> new ArrayList<>()).add(id2);
                        adj.computeIfAbsent(id2, k -> new ArrayList<>()).add(id1);
                    }
                }
            } catch (Exception e) {
                continue;
            }
        }
    }

    int startId = start[0] * n + start[1];
    int endId = end[0] * n + end[1];

    // BFS
    boolean[] visited = new boolean[n * n];
    Queue<Integer> queue = new LinkedList<>();
    queue.offer(startId);
    visited[startId] = true;

    while (!queue.isEmpty()) {
        int current = queue.poll();
        if (current == endId) {
            return "can be travelled";
        }
        List<Integer> neighbors = adj.getOrDefault(current, Collections.emptyList());
        for (int neighbor : neighbors) {
            if (!visited[neighbor]) {
                visited[neighbor] = true;
                queue.offer(neighbor);
            }
        }
    }

    return "cannot be travelled";
}

