public static String convertDatesToWeekdays(String date) {
    if (date == null || date.isEmpty()) {
        return "Invalid date";
    }

    String[] parts = date.split("\\s+");
    if (parts.length != 3) {
        return "Invalid date";
    }

    int month;
    int day;
    int year;

    try {
        month = Integer.parseInt(parts[0]);
        day = Integer.parseInt(parts[1]);
        year = Integer.parseInt(parts[2]);
    } catch (NumberFormatException e) {
        return "Invalid date";
    }

    // Validate ranges
    if (month < 1 || month > 12 || day < 1 || day > 31 || year < 1) {
        return "Invalid date";
    }

    // Create a Calendar instance
    java.util.Calendar calendar = java.util.GregorianCalendar.getInstance();
    calendar.clear();
    calendar.set(year, month - 1, day);

    // Check if the date is valid (e.g., February 30)
    if (calendar.get(java.util.Calendar.MONTH) != month - 1 || 
        calendar.get(java.util.Calendar.DAY_OF_MONTH) != day) {
        return "Invalid date";
    }

    int weekday = calendar.get(java.util.Calendar.DAY_OF_WEEK);
    String[] weekdayNames = {"", "Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"};
    String monthNames = {"", "January", "February", "March", "April", "May", "June", 
                         "July", "August", "September", "October", "November", "December"};

    String weekdayName = weekdayNames[weekday];
    String monthName = monthNames[month];

    return String.format("%s %d, %d is a %s", monthName, day, year, weekdayName);
}

public int[] twoSum(int[] nums, int target) {
    if (nums == null || nums.length < 2) {
        return new int[0];
    }

    Map<Integer, Integer> map = new HashMap<>();
    for (int i = 0; i < nums.length; i++) {
        int complement = target - nums[i];
        if (map.containsKey(complement)) {
            return new int[]{map.get(complement), i};
        }
        map.put(nums[i], i);
    }

    return new int[0];
}

public int search(int[] nums, int target) {
    if (nums == null || nums.length == 0) {
        return -1;
    }

    int left = 0;
    int right = nums.length - 1;

    while (left <= right) {
        int mid = left + (right - left) / 2;

        if (nums[mid] == target) {
            return mid;
        }

        // Left half is sorted
        if (nums[left] <= nums[mid]) {
            // Target is in the left sorted portion
            if (nums[left] <= target && target < nums[mid]) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        } else {
            // Right half is sorted
            if (nums[mid] < target && target <= nums[right]) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
    }

    return -1;
}

public double trimMean(int[] arr) {
    int n = arr.length;
    if (n == 0) {
        return 0.0;
    }
    int trimCount = (int) (n * 0.05);
    int[] sorted = arr.clone();
    java.util.Arrays.sort(sorted);

    double sum = 0.0;
    for (int i = trimCount; i < n - trimCount; i++) {
        sum += sorted[i];
    }
    int remainingCount = n - 2 * trimCount;
    if (remainingCount == 0) {
        return 0.0;
    }
    return sum / remainingCount;
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null || k <= 0) {
        return false;
    }
    int n = arr.length;
    if (n % 2 != 0) {
        return false;
    }

    // Count remainders
    int[] counts = new int[k];
    for (int num : arr) {
        int rem = num % k;
        if (rem < 0) {
            rem += k;
        }
        counts[rem]++;
    }

    // Check remainder 0: must be even
    if (counts[0] % 2 != 0) {
        return false;
    }

    // Check pairs: remainder i must pair with remainder (k - i)
    for (int i = 1; i <= k / 2; i++) {
        int j = k - i;
        if (i == j) {
            // i == k - i, which means 2i == k, so i == k/2 (when k is even)
            if (counts[i] % 2 != 0) {
                return false;
            }
        } else {
            if (counts[i] != counts[j]) {
                return false;
            }
        }
    }

    return true;
}

