public String sortString(String s) {
        if (s == null || s.length() == 0) {
            return s;
        }

        // Count frequency of each character
        int[] count = new int[26];
        for (char c : s.toCharArray()) {
            count[c - 'a']++;
        }

        StringBuilder result = new StringBuilder();
        boolean finished = false;
        while (!finished) {
            // Forward pass: pick smallest, then smallest greater than last, etc.
            for (int i = 0; i < 26; i++) {
                if (count[i] > 0) {
                    result.append((char) ('a' + i));
                    count[i]--;
                }
            }

            // Backward pass: pick largest, then largest smaller than last, etc.
            for (int i = 25; i >= 0; i--) {
                if (count[i] > 0) {
                    result.append((char) ('a' + i));
                    count[i]--;
                }
            }

            // Check if all characters have been picked
            finished = true;
            for (int c : count) {
                if (c > 0) {
                    finished = false;
                    break;
                }
            }
        }

        return result.toString();
    }

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) return false;

    long sum = 0;
    int min = Integer.MAX_VALUE;
    int max = Integer.MIN_VALUE;
    for (int num : nums) {
        sum += num;
        if (num < min) min = num;
        if (num > max) max = num;
    }

    // Check if the average can be represented with integer arithmetic
    // We don't need the actual average, but we need to check if sum * k % n == 0 for some k in [1, n-1]
    // Actually, the key insight: if we have a subset of size k with average equal to overall average,
    // then subset_sum * n == sum * k, so sum * k must be divisible by n (actually the condition is subset_sum = sum * k / n, which requires sum * k % n == 0)

    // DP: we want to find a subset of size k (1 <= k <= n/2) such that subset_sum = sum * k / n
    // This requires sum * k % n == 0

    // Map from sum to set of counts (or we can use bitset for sums, but sums can be negative/positive and large)
    // Use a map: key = sum, value = set of possible subset sizes (counts) that achieve this sum

    // Since n <= 16 (typical for such problems), we can use a different approach.
    // But for general n, we can use DP with a map.

    // Actually, let's use a map from sum to a set of counts.
    // Initialize: we can have subset of size 0 with sum 0.
    Map<Long, Set<Integer>> dp = new HashMap<>();
    dp.put(0L, new HashSet<>());
    dp.get(0L).add(0);

    for (int num : nums) {
        Map<Long, Set<Integer>> newDp = new HashMap<>();
        for (Map.Entry<Long, Set<Integer>> entry : dp.entrySet()) {
            long s = entry.getKey();
            Set<Integer> counts = entry.getValue();
            // Carry over existing entries
            for (Integer count : counts) {
                newDp.computeIfAbsent(s, k -> new HashSet<>()).add(count);
            }
            // Add the current number
            for (Integer count : counts) {
                long newSum = s + num;
                int newCount = count + 1;
                newDp.computeIfAbsent(newSum, k -> new HashSet<>()).add(newCount);
            }
        }
        dp = newDp;
    }

    // Now check for any k in [1, n-1] such that sum * k % n == 0 and there exists a subset of size k with sum = sum * k / n
    // To avoid duplicates, we only check k from 1 to n/2 (since if a subset of size k works, the complement of size n-k also works)
    for (int k = 1; k <= n / 2; k++) {
        if (sum * k % n == 0) {
            long targetSum = sum * k / n;
            if (dp.containsKey(targetSum)) {
                Set<Integer> counts = dp.get(targetSum);
                if (counts.contains(k)) {
                    return true;
                }
            }
        }
    }

    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    if (cost.length == 1) {
        return cost[0];
    }

    int n = cost.length;
    // dp[i] represents the minimum cost to reach step i
    // We can reach step i from step i-1 or i-2
    // To reach the top (beyond the last step), we can come from step n-1 or n-2

    int prev2 = 0; // cost to reach index 0 (if we start here, we pay cost[0] when we leave)
    int prev1 = 0; // cost to reach index 1 (if we start here, we pay cost[1] when we leave)

    // Actually, let's reframe: dp[i] = minimum cost to reach step i
    // dp[0] = 0 (we can start at step 0, no cost to get there, but we'll pay when we leave)
    // This is tricky. Let me use the standard approach:

    // Let dp[i] be the minimum cost to reach step i (standing on step i)
    // But actually, we can also think of it as: to reach the top (index n), 
    // the last step we stand on is either n-1 or n-2.

    // Standard solution:
    // dp[i] = cost[i] + min(dp[i-1], dp[i-2])
    // Base: dp[0] = cost[0], dp[1] = cost[1]
    // Answer: min(dp[n-1], dp[n-2])

    if (cost.length == 1) {
        return cost[0];
    }

    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];

    for (int i = 2; i < n; i++) {
        dp[i] = cost[i] + Math.min(dp[i-1], dp[i-2]);
    }

    return Math.min(dp[n-1], dp[n-2]);
}

public int uniqueMorseRepresentations(String[] words) {
    String[] morseCodes = {".-","-...","-.-.","-..",".","..-.","--.","....","..",".---","-.-",".-..","--","-.","---",".--.","--.-",".-.","...","-","..-","...-",".--","-..-","-.--","--.."};
    java.util.Set<String> seen = new java.util.HashSet<>();
    for (String word : words) {
        StringBuilder sb = new StringBuilder();
        for (char c : word.toCharArray()) {
            sb.append(morseCodes[c - 'a']);
        }
        seen.add(sb.toString());
    }
    return seen.size();
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || s.length() < k) {
        return false;
    }
    int total = 1 << k;
    boolean[] seen = new boolean[total];
    int uniqueCount = 0;

    for (int i = 0; i <= s.length() - k; i++) {
        int code = 0;
        for (int j = i; j < i + k; j++) {
            code = (code << 1) | (s.charAt(j) - '0');
        }
        if (!seen[code]) {
            seen[code] = true;
            uniqueCount++;
            if (uniqueCount == total) {
                return true;
            }
        }
    }

    return uniqueCount == total;
}

public int isPrefixOfWord(String sentence, String searchWord) {
    if (sentence == null || sentence.isEmpty() || searchWord == null || searchWord.isEmpty()) {
        return -1;
    }

    String[] words = sentence.split(" ");
    for (int i = 0; i < words.length; i++) {
        if (words[i].startsWith(searchWord)) {
            return i;
        }
    }
    return -1;
}

public int minInsertions(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }

    int openNeeded = 0;
    int insertions = 0;

    for (char c : s.toCharArray()) {
        if (c == '(') {
            openNeeded++;
        } else {
            openNeeded--;
            if (openNeeded < 0) {
                openNeeded = 0;
                insertions++;
            }
        }
    }

    return insertions + openNeeded;
}

public int minOperations(int n) {
    // The array is arr[i] = 2*i + 1 for i from 0 to n-1
    // The sum of the array is sum_{i=0}^{n-1} (2*i + 1) = 2*(n*(n-1)/2) + n = n*(n-1) + n = n^2
    // Since total sum is n^2, to make all elements equal, each element must become n^2 / n = n.
    // So we need to make all elements equal to n.
    // For each index i, the difference from n is: | (2*i + 1) - n |
    // The number of operations is half the sum of absolute differences (since each operation moves 1 unit from one element to another, reducing total absolute difference by 2).
    // Actually, the minimum number of operations is the sum of positive differences (or equivalently, sum of negative differences in absolute value), which is the same as half the sum of absolute differences.

    // Let's compute: sum_{i=0}^{n-1} |2*i + 1 - n|
    // Then the answer is that sum / 2.

    // We can derive a closed form.
    // Let's think: for i < n/2, (2*i+1) < n (roughly), and for i >= n/2, (2*i+1) >= n.

    long totalDiff = 0;
    for (int i = 0; i < n; i++) {
        totalDiff += Math.abs((2L * i + 1) - n);
    }
    return (int)(totalDiff / 2);
}

public int highestAltitude(int[] gain) {
    if (gain == null || gain.length == 0) {
        return 0;
    }
    int currentAltitude = 0;
    int highestAltitude = 0;
    for (int g : gain) {
        currentAltitude += g;
        if (currentAltitude > highestAltitude) {
            highestAltitude = currentAltitude;
        }
    }
    return highestAltitude;
}

public int maxAbsoluteSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    int maxSum = 0;
    int minSum = 0;
    int currMax = 0;
    int currMin = 0;
    for (int num : nums) {
        currMax = Math.max(num, currMax + num);
        currMin = Math.min(num, currMin + num);
        maxSum = Math.max(maxSum, currMax);
        minSum = Math.min(minSum, currMin);
    }
    return Math.max(Math.abs(maxSum), Math.abs(minSum));
}

public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        return 0;
    }

    // Generate Fibonacci numbers up to k
    java.util.List<Integer> fibs = new java.util.ArrayList<>();
    int a = 1, b = 1;
    fibs.add(a);
    while (b <= k) {
        fibs.add(b);
        int next = a + b;
        a = b;
        b = next;
        if (a > k && b > k) break;
    }

    // Convert to array for easier access
    int[] f = new int[fibs.size()];
    for (int i = 0; i < f.length; i++) {
        f[i] = fibs.get(i);
    }

    int n = f.length;
    // dp[i] = minimum number of Fibonacci numbers to sum to f[i]
    int[] dp = new int[n];
    for (int i = 0; i < n; i++) {
        if (f[i] <= k) {
            dp[i] = 1;
        } else {
            dp[i] = Integer.MAX_VALUE;
        }
    }

    // For each Fibonacci number, try subtracting it and see if we can form the rest
    // Actually, we need to find min number of Fibonacci numbers summing to k.
    // We can iterate through Fibonacci numbers less than or equal to k.

    // Alternative approach: greedy method (works for Fibonacci as it's a complete sequence)
    // But let's do DP properly.
    // dp[i] = min number of Fibonacci numbers to sum to i, for i from 1 to k
    int[] dpNum = new int[k + 1];
    for (int i = 1; i <= k; i++) {
        dpNum[i] = Integer.MAX_VALUE;
    }

    for (int target = 1; target <= k; target++) {
        for (int j = 0; j < n && f[j] <= target; j++) {
            if (dpNum[target - f[j]] + 1 < dpNum[target]) {
                dpNum[target] = dpNum[target - f[j]] + 1;
            }
        }
    }

    return dpNum[k];
}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }

    int count = 0;
    for (int i = 1; i <= n; i++) {
        if (n % i == 0) {
            count++;
            if (count == k) {
                return i;
            }
        }
    }

    return -1;
}

public String makeGood(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }

    StringBuilder stack = new StringBuilder();

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        int len = stack.length();
        if (len > 0) {
            char prev = stack.charAt(len - 1);
            if ((prev - 'a' == c - 'A') || (c - 'a' == prev - 'A')) {
                // They are matching uppercase/lowercase pair
                if (Math.abs(prev - c) == 32) {
                    stack.deleteCharAt(len - 1);
                    continue;
                }
            }
        }
        stack.append(c);
    }

    return stack.toString();
}

