public int minOperations(String[] logs) {
    int depth = 0;
    for (String log : logs) {
        if (log.equals("../")) {
            if (depth > 0) {
                depth--;
            }
        } else if (!log.equals("./")) {
            depth++;
        }
    }
    return depth;
}

public String getSmallestString(int n, int k) {
    char[] result = new char[n];
    // Initialize all with 'a'
    for (int i = 0; i < n; i++) {
        result[i] = 'a';
    }

    // Minimum value is n (all 'a's)
    int remaining = k - n;

    // We want lexicographically smallest, so we should put as much extra value in the last characters as possible
    for (int i = n - 1; i >= 0; i--) {
        if (remaining <= 0) break;
        // Max we can add to this position is 25 (from 'a' to 'z')
        int add = Math.min(remaining, 25);
        result[i] = (char) ('a' + add);
        remaining -= add;
    }

    return new String(result);
}

