public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        throw new IllegalArgumentException("Input array must not be null or empty");
    }

    int ones = 0;
    int twos = 0;
    int threes = 0;

    for (int num : nums) {
        threes = threes & (twos & num);
        twos = twos & ~(ones & num);
        ones = ones & ~(twos & num);
        twos = twos | (ones & num);
        ones = ones | (twos & num);

        // Reset bits that appeared three times
        ones = ones & ~threes;
        twos = twos & ~threes;
        threes = 0;
    }

    return ones;
}

