public static int countDigitOne(int n) {
    if (n < 0) {
        return 0;
    }

    int count = 0;
    for (long factor = 1; factor <= n; factor *= 10) {
        long left = n / (factor * 10);
        long current = (n / factor) % 10;
        long right = n % factor;

        if (current > 1) {
            count += (left + 1) * factor;
        } else if (current == 1) {
            count += left * factor + right + 1;
        } else {
            count += left * factor;
        }
    }

    return count;
}

public static boolean isPowerOfTwo(int n) {
    if (n <= 0) {
        return false;
    }
    return (n & (n - 1)) == 0;
}

public static int addDigits(int num) {
    if (num < 0) {
        throw new IllegalArgumentException("Input must be a non-negative integer.");
    }
    while (num >= 10) {
        int sum = 0;
        while (num > 0) {
            sum += num % 10;
            num /= 10;
        }
        num = sum;
    }
    return num;
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int m = mat.length;
    int n = mat[0].length;
    int maxLen = 0;

    // horizontal, vertical, diagonal, anti-diagonal
    int[][][] dp = new int[m][n][4];

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                // horizontal: from left
                dp[i][j][0] = 1 + (j > 0 ? dp[i][j - 1][0] : 0);

                // vertical: from top
                dp[i][j][1] = 1 + (i > 0 ? dp[i - 1][j][1] : 0);

                // diagonal: from top-left
                dp[i][j][2] = 1 + (i > 0 && j > 0 ? dp[i - 1][j - 1][2] : 0);

                // anti-diagonal: from top-right
                dp[i][j][3] = 1 + (i > 0 && j < n - 1 ? dp[i - 1][j + 1][3] : 0);

                for (int k = 0; k < 4; k++) {
                    if (dp[i][j][k] > maxLen) {
                        maxLen = dp[i][j][k];
                    }
                }
            }
        }
    }

    return maxLen;
}

public static String addThousandSeparator(int n) {
    if (n == 0) {
        return "0";
    }

    boolean negative = n < 0;
    int absN = Math.abs(n);
    String digits = String.valueOf(absN);

    StringBuilder result = new StringBuilder();
    int length = digits.length();
    int firstGroupSize = length % 3;

    if (firstGroupSize > 0) {
        result.append(digits, 0, firstGroupSize);
    }

    for (int i = firstGroupSize; i < length; i += 3) {
        if (i > firstGroupSize) {
            result.append('.');
        }
        result.append(digits, i, i + 3);
    }

    if (negative) {
        result.insert(0, '-');
    }

    return result.toString();
}

public static int squarePermutations(int[] A) {
    if (A == null || A.length == 0) {
        return 0;
    }

    int n = A.length;

    // Precompute which pairs sum to a perfect square
    boolean[][] squareSum = new boolean[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i != j) {
                int sum = A[i] + A[j];
                int sqrt = (int) Math.sqrt(sum);
                if (sqrt * sqrt == sum) {
                    squareSum[i][j] = true;
                }
            }
        }
    }

    int[] counts = new int[2];
    counts[0] = 0;
    counts[1] = 1;
    int[] last = new int[1];
    int[] count = new int[1];
    count[0] = 0;

    // Use backtracking with a list to track current permutation
    List<Integer> path = new ArrayList<>();
    boolean[] used = new boolean[n];

    // For small n, use DFS backtracking
    backtrack(A, squareSum, used, path, n, count);

    return count[0];
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }

    int n = heights.length;
    int[] stack = new int[n];
    int top = -1;
    int maxArea = 0;

    for (int i = 0; i <= n; i++) {
        int currentHeight = (i < n) ? heights[i] : 0;

        while (top >= 0 && heights[stack[top]] > currentHeight) {
            int height = heights[stack[top--]];
            int width = (top >= 0) ? (i - stack[top] - 1) : i;
            maxArea = Math.max(maxArea, height * width);
        }

        stack[++top] = i;
    }

    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int totalElements = rows * cols;
    int[] result = new int[totalElements];

    int index = 0;
    // There are (rows + cols - 1) diagonals
    for (int d = 0; d < rows + cols - 1; d++) {
        if (d % 2 == 0) {
            // Even diagonal: traverse from top-right to bottom-left
            int startRow = d < cols ? 0 : d - cols + 1;
            int startCol = d < cols ? d : cols - 1;
            int currentRow = startRow;
            int currentCol = startCol;
            while (currentRow < Math.min(d + 1, rows) && currentCol >= 0 && currentCol < cols) {
                result[index++] = mat[currentRow][currentCol];
                currentRow++;
                currentCol--;
            }
        } else {
            // Odd diagonal: traverse from bottom-left to top-right
            int startRow = d < cols ? d : rows - 1;
            int startCol = d < cols ? 0 : d - rows + 1;
            int currentRow = Math.min(startRow, rows - 1);
            int currentCol = Math.min(startCol, cols - 1);
            while (currentRow >= 0 && currentCol < cols && currentRow < rows) {
                result[index++] = mat[currentRow][currentCol];
                currentRow--;
                currentCol++;
            }
        }
    }

    return result;
}

public static int findSmallestInteger(int n) {
    if (n <= 0) {
        return -1;
    }

    char[] digits = Integer.toString(n).toCharArray();
    int len = digits.length;

    // Find the first digit from the right that is smaller than the digit to its right
    int i = len - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }

    if (i < 0) {
        return -1;
    }

    // Find the smallest digit greater than digits[i] from the right
    int j = len - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }

    // Swap digits[i] and digits[j]
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Reverse the suffix starting at i+1
    int left = i + 1;
    int right = len - 1;
    while (left < right) {
        char t = digits[left];
        digits[left] = digits[right];
        digits[right] = t;
        left++;
        right--;
    }

    // Convert back to integer
    int result;
    try {
        result = Integer.parseInt(new String(digits));
    } catch (NumberFormatException e) {
        return -1;
    }

    return result > n ? result : -1;
}

