public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }

    // Check if the three points are collinear using cross product
    // Points A, B, C are collinear if (B-A) x (C-A) == 0
    double x1 = points[0][0], y1 = points[0][1];
    double x2 = points[1][0], y2 = points[1][1];
    double x3 = points[2][0], y3 = points[2][1];

    // Calculate cross product of vectors AB and AC
    double cross = (x2 - x1) * (y3 - y1) - (x3 - x1) * (y2 - y1);

    // If cross product is zero, points are collinear, not a boomerang
    return Math.abs(cross) > 1e-9;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        return 0;
    }

    int[] ugly = new int[n];
    ugly[0] = 1;

    int i2 = 0, i3 = 0, i5 = 0;
    int nextMultiple2 = 2;
    int nextMultiple3 = 3;
    int nextMultiple5 = 5;

    for (int i = 1; i < n; i++) {
        int nextUgly = Math.min(nextMultiple2, Math.min(nextMultiple3, nextMultiple5));
        ugly[i] = nextUgly;

        if (nextUgly == nextMultiple2) {
            i2++;
            nextMultiple2 = ugly[i2] * 2;
        }
        if (nextUgly == nextMultiple3) {
            i3++;
            nextMultiple3 = ugly[i3] * 3;
        }
        if (nextUgly == nextMultiple5) {
            i5++;
            nextMultiple5 = ugly[i5] * 5;
        }
    }

    return ugly[n - 1];
}

public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }

    int maxEnergy = 1;
    int currentEnergy = 1;

    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            currentEnergy++;
        } else {
            currentEnergy = 1;
        }
        if (currentEnergy > maxEnergy) {
            maxEnergy = currentEnergy;
        }
    }

    return maxEnergy;
}

public static List<Integer> lexicalOrder(int n) {
        List<Integer> result = new ArrayList<>();
        if (n <= 0) return result;

        int current = 1;
        for (int i = 0; i < n; i++) {
            result.add(current);
            if (current * 10 <= n) {
                current *= 10;
            } else {
                while (current % 10 == 9 || current + 1 > n) {
                    current /= 10;
                }
                current++;
            }
        }
        return result;
    }

public static int calculateUniqueSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }

    java.util.Map<Integer, Integer> countMap = new java.util.HashMap<>();
    for (int num : nums) {
        countMap.put(num, countMap.getOrDefault(num, 0) + 1);
    }

    int sum = 0;
    for (java.util.Map.Entry<Integer, Integer> entry : countMap.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }

    return sum;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer");
    }

    // dp[i] will store the minimum number of perfect square numbers that sum to i
    int[] dp = new int[n + 1];
    dp[0] = 0;

    for (int i = 1; i <= n; i++) {
        dp[i] = Integer.MAX_VALUE;
        for (int j = 1; j * j <= i; j++) {
            int prev = dp[i - j * j];
            if (prev != Integer.MAX_VALUE && prev + 1 < dp[i]) {
                dp[i] = prev + 1;
            }
        }
    }

    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }
    String[] words = s.split(" ", -1);
    StringBuilder result = new StringBuilder();
    for (int i = 0; i < words.length; i++) {
        StringBuilder wordBuilder = new StringBuilder(words[i]);
        wordBuilder.reverse();
        result.append(wordBuilder.toString());
        if (i < words.length - 1) {
            result.append(" ");
        }
    }
    return result.toString();
}
